"""Contract test — anti_overfit_audit.json isolation discipline.

Background
----------
``audit_dashboard/data/anti_overfit_audit.json`` is a VERDICT sidecar
generated by ``tools/anti_overfit_audit_sidecar.py``. It carries
per-strategy DSR/Sharpe/PBO/RC verdicts (Lopez de Prado AFML eq 14.5).
It currently carries::

    "_schema_note": "Generated by tools/anti_overfit_audit_sidecar.py; ..."
    "anti_overfit_audit_only": True

The payload encodes VERDICT data (EDGE_LIKELY_REAL / UNDETERMINED /
OVERFIT_LIKELY classification per strategy) — never a sizing signal.
The schema contract is the ``anti_overfit_audit_only: True`` gate flag
(machine-readable proxy for "this is verdict data, not sizing input").

That contract is currently a docstring — Python has no way to enforce
it. This test enforces it pre-merge so a future ``tools/consume_picks.py``
that silently re-ingests this verdict sidecar as a sizing source FAILS
the test instead of shipping to production.

The contract — two acceptable signals in a consumer candidate:

1. The file references the gate flag ``anti_overfit_audit_only``, OR
2. The file carries an explicit ``# allowed: anti-overfit-audit
   consumer`` comment on its own line.

See:
- ``audit_dashboard/data/anti_overfit_audit.json`` for the payload +
  its ``_schema_note`` / ``anti_overfit_audit_only`` fields
- ``tools/anti_overfit_audit_sidecar.py`` for the writer
"""

from __future__ import annotations

import json
import os
import re
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parent.parent

SCAN_ROOTS = [
    REPO / "tools",
    REPO / "audit_trail",
    REPO / "alpha_engine",
]

EXEMPT_BASENAMES = {
    "anti_overfit_audit_sidecar.py",            # writer
    "test_no_anti_overfit_audit_consumer.py",    # self
}

EXEMPT_SUFFIX_PARTS = ("__pycache__", ".pyc")

SIDECAR_FILENAME = "anti_overfit_audit.json"
GUARD_FLAG = "anti_overfit_audit_only"
ALLOW_COMMENT_RE = re.compile(
    r"#\s*allowed:\s*anti-overfit-audit\s+consumer\b"
)
SIDECAR_CONTRACT_KEYS_REQUIRED = ("_schema_note", "anti_overfit_audit_only")

CRON_MODE = os.environ.get("ANTI_OVERFIT_AUDIT_CRON_MODE", "") == "1"


def _consumes_sidecar(content: str) -> bool:
    if SIDECAR_FILENAME not in content:
        return False
    intent_patterns = (
        "open(", "read_text", "read_bytes",
        "json.load", "json.loads",
        "yaml.safe_load", "yaml.load",
        "tomllib.load",
        ".load(", ".loads(",
    )
    return any(pat in content for pat in intent_patterns)


def _carries_guard(content: str) -> bool:
    return GUARD_FLAG in content


def _carries_allow_marker(content: str) -> bool:
    return bool(ALLOW_COMMENT_RE.search(content))


def _is_exempt(path: Path) -> bool:
    if path.name in EXEMPT_BASENAMES:
        return True
    if any(part in EXEMPT_SUFFIX_PARTS for part in path.parts):
        return True
    return False


def _scan_files():
    for root in SCAN_ROOTS:
        if not root.exists():
            continue
        for path in root.rglob("*.py"):
            if not path.is_file():
                continue
            if _is_exempt(path):
                continue
            yield path


def test_no_unguarded_consumer_in_scan_roots():
    violations: list[str] = []
    for path in _scan_files():
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        if not _consumes_sidecar(content):
            continue
        if _carries_allow_marker(content):
            continue
        if _carries_guard(content):
            continue
        violations.append(path.relative_to(REPO).as_posix())

    assert not violations, (
        "Unguarded consumers of anti_overfit_audit.json detected. "
        "Every *.py that opens the sidecar under {tools/, audit_trail/, "
        "alpha_engine/} must EITHER reference the `anti_overfit_audit_only` "
        "gate-flag string OR carry a line reading exactly "
        "`# allowed: anti-overfit-audit consumer`. "
        f"Violations: {violations}"
    )


def test_sidecar_payload_carries_required_contract_keys():
    sidecar_path = REPO / "audit_dashboard" / "data" / SIDECAR_FILENAME

    if not sidecar_path.exists():
        if CRON_MODE:
            pytest.fail(
                f"HARD REGRESSION: {sidecar_path.relative_to(REPO).as_posix()} "
                "is missing AFTER the anti-overfit audit step ran "
                "(ANTI_OVERFIT_AUDIT_CRON_MODE=1). Investigate the writer "
                "(tools/anti_overfit_audit_sidecar.py) before re-running."
            )
        pytest.skip(
            f"{sidecar_path.relative_to(REPO).as_posix()} not yet produced; "
            "the anti-overfit cron step will land it."
        )

    payload = json.loads(sidecar_path.read_text(encoding="utf-8"))

    missing = [k for k in SIDECAR_CONTRACT_KEYS_REQUIRED if k not in payload]
    assert not missing, (
        f"{sidecar_path.relative_to(REPO).as_posix()} is missing required "
        f"contract keys: {missing}. Both `_schema_note` and "
        "`anti_overfit_audit_only` are required."
    )

    assert payload["anti_overfit_audit_only"] is True, (
        "anti_overfit_audit_only must be a strict boolean True; got "
        f"{payload['anti_overfit_audit_only']!r} instead."
    )


def test_exempt_set_includes_writer_and_self():
    today = REPO / "tests" / "test_no_anti_overfit_audit_consumer.py"
    writer = REPO / "tools" / "anti_overfit_audit_sidecar.py"
    assert today.name in EXEMPT_BASENAMES
    assert writer.name in EXEMPT_BASENAMES, (
        "EXEMPT_BASENAMES must contain "
        f"{writer.name!r} (the anti-overfit audit payload's writer)."
    )
